// Biomedical Debate Practice Test 6. Original questions written for Valus on the 2026–27 resolution,
// "Limited healthcare resources should be allocated to patients with the greatest likelihood of
// long-term survival." Slightly harder than the sample items, covering material not used in Tests 1–5.
import {q, mix} from './q.js';
const LEVY='Levy, Breaking the Age Code (2022)', BH='Bognar & Hirose, The Ethics of Health Care Rationing', EMAN='Emanuel et al., NEJM (2020)', PERSAD='Persad, Wertheimer & Emanuel, The Lancet (2009)', OPTN='Organ Procurement and Transplantation Network';
const SCAR='Scarcity and Levels of Allocation', ETH='Ethical Theories and Principles', CRIT='Allocation Criteria and Frameworks', CASE='Real-World Allocation Cases', AGE='Aging, Longevity and Equity';

export default {
 id:'biomedical-debate-6',
 event:'Biomedical Debate',
 title:'Practice Test 6',
 subtitle:'Round One test simulation on the 2026–27 resolution',
 minutes:60,
 sources:'Levy’s Breaking the Age Code, Bognar and Hirose’s The Ethics of Health Care Rationing and published allocation frameworks',
 plan:[{area:'Resolution: Allocating Limited Healthcare Resources',weight:100,topics:[SCAR,ETH,CRIT,CASE,AGE]}],
 questions:mix([
  q(SCAR,'A program accepts only patients considered most likely to benefit and turns away higher-risk patients. Which form of rationing is this?','Rationing by selection',['Rationing by deterrence','Rationing by dilution','Rationing by delay'],'A','Selection can improve average outcomes while leaving the highest-risk patients without care.',BH),
  q(SCAR,'Stopping a treatment earlier than would be ideal in order to free resources for others is rationing by:','Termination',['Denial','Deflection','Deterrence'],'B','Termination is common in crisis triage when patients are reassessed and resources reassigned.',BH),
  q(SCAR,'A patented drug is cheap to make but priced so high that many patients cannot get it. What kind of scarcity is this?','Artificial scarcity created by price',['Absolute scarcity of the raw materials','Natural scarcity of donated tissue','Temporary scarcity from a natural disaster'],'C','Unlike donor organs, the supply of such a drug could be expanded if price barriers were removed.',BH),
  q(SCAR,'Why do U.S. drug shortages most often involve older generic sterile injectable drugs?','Low profits lead few companies to make them',['They are banned in most states','They expire within one day','They can be made only by hospitals'],'D','When one of a few makers has a quality problem, there is little backup supply.',BH),
  q(SCAR,'The Association of American Medical Colleges projects a U.S. shortage of up to about how many physicians by 2036?','86,000',['860','8,600','860,000'],'A','Physician shortages ration care through longer waits and fewer services in underserved areas.',BH),
  q(SCAR,'The federal government designates areas with too few primary care, dental or mental health clinicians as:','Health Professional Shortage Areas',['Federal Opportunity Zones','Rural Enterprise Zones','Medically Adequate Service Areas'],'B','Clinicians who work in these areas may qualify for loan repayment programs.',BH),
  q(SCAR,'When a person registers as an organ donor, most U.S. states treat that choice as legal consent that families cannot override. What is this called?','First-person authorization',['Presumed (opt-out) consent','Mandated choice registration','Next-of-kin family veto'],'C','First-person authorization respects the donor’s own decision.',OPTN),
  q(SCAR,'Transplanting organs from genetically modified pigs into humans to ease the organ shortage is called:','Xenotransplantation',['Autotransplantation','Allotransplantation','Isotransplantation'],'D','The first pig heart and kidney transplants into living patients were performed in the 2020s.',OPTN),
  q(SCAR,'About what share of deceased-donor kidneys recovered in the U.S. in recent years were not transplanted and were discarded?','About one in four',['About one in 100','About one in two','Almost none'],'A','Reducing discards is one way to increase supply without new donors.',OPTN),
  q(ETH,'Thomas Scanlon’s contractualism says an allocation rule is acceptable if it is one that:','No one could reasonably reject',['Maximizes total happiness','Is chosen by a market','Treats people as means only'],'B','Contractualists ask whether each affected person could reasonably reject a principle.',BH),
  q(ETH,'An allocation scheme that gives priority to people based on what they have earned or deserve, such as past healthy choices, is called:','Desert-based allocation',['Need-based allocation','Lottery-based allocation','Age-based allocation'],'C','Critics say judging desert is unreliable and can punish people for circumstances beyond their control.',BH),
  q(ETH,'Some ethicists argue that withdrawing a ventilator is morally different from never starting it. Which distinction is this?','Doing versus allowing',['Fact versus value','Act versus rule','Means versus ends'],'D','Many ethicists and guidelines hold that withholding and withdrawing are morally equivalent.',BH),
  q(ETH,'The principle that public health restrictions should be no greater than needed to achieve their goal is called:','Proportionality',['Reciprocity','Solidarity','Utility'],'A','Proportionality asks whether the benefits of a policy justify the burdens it places on people.',BH),
  q(ETH,'The value that calls on members of a society to share risks and support one another during a crisis is called:','Solidarity',['Autonomy','Libertarianism','Egoism'],'B','Solidarity is often cited to justify shared sacrifices during pandemics.',BH),
  q(ETH,'Lingering distress that clinicians feel after a morally difficult decision, even when they acted correctly, is called:','Moral residue',['Moral hazard','Moral luck','Moral relativism'],'C','Repeated moral residue can build up and contribute to burnout.',BH),
  q(ETH,'A clinician refuses to take part in a procedure because it violates their deeply held moral beliefs. What is this called?','Conscientious objection',['Moral hazard','Informed refusal','Civil disobedience'],'D','Most policies require objecting clinicians to make sure patients can still get care elsewhere.',BH),
  q(ETH,'A group of randomly chosen citizens hears evidence and recommends health priorities. What is this method called?','A citizens’ jury',['A grand jury','A focus group of experts','A legislative hearing'],'A','Public deliberation can give allocation rules more legitimacy and reflect community values.',BH),
  q(ETH,'The idea that every person has a claim to the highest attainable standard of health, which governments must work toward, reflects which approach?','A rights-based approach',['A market-based approach','An egoist approach','A desert-based approach'],'B','Rights-based approaches stress government duties and the needs of the most vulnerable.',BH),
  q(CRIT,'During COVID-19, several states removed points for predicted survival beyond one year from their triage plans. What was the main reason?','They were unreliable and penalized disability',['Federal law required states to use only one-year predictions','Short-term survival predictions cost far more to calculate','Long-term predictions gave extra priority to older patients'],'C','Critics argued that judging years of survival after recovery penalized chronic illness and disability.',EMAN),
  q(CRIT,'The SOFA score assesses how many organ systems?','Six',['Three','Four','Ten'],'D','It covers the lungs, blood clotting, liver, heart and circulation, brain and kidneys.',EMAN),
  q(CRIT,'What is the range of the Glasgow Coma Scale, which forms part of the SOFA score?','3 to 15',['0 to 10','1 to 5','0 to 100'],'A','It rates eye, verbal and motor responses; lower scores mean a more serious reduction in consciousness.',EMAN),
  q(CRIT,'In SOFA-based crisis triage, which patients usually receive the highest priority?','Those with the lowest scores',['Those with the highest scores','Those who arrived last','Those with private insurance'],'B','Lower SOFA scores mean less organ failure and a better chance of short-term survival.',EMAN),
  q(CRIT,'Patient A has an 80% chance of survival and would then live about 5 more years. Patient B has a 40% chance and would then live about 20 more years. Who has more expected life-years?','Patient B, with 8 expected life-years',['Patient A, with 4 expected life-years','Patient A, with 5 expected life-years','Patient B, with 20 expected life-years'],'C','Expected life-years = chance × years: A = 0.8 × 5 = 4 and B = 0.4 × 20 = 8, so the two survival goals can point in different directions.',BH),
  q(CRIT,'Some economists give extra value to health gains for disadvantaged groups in cost-effectiveness analysis. What are these called?','Equity weights',['Discount rates','Utility caps','Severity scores'],'D','Equity weights try to combine efficiency with concern for fairness.',BH),
  q(CRIT,'A survival-prediction tool trained mostly on data from one group performs worse for others. What is this problem called?','Algorithmic bias',['Regression to the mean','Publication bias','Recall bias'],'A','Biased tools can turn past inequities into future allocation decisions.',BH),
  q(CRIT,'Some crisis frameworks consider how much of a resource a patient will need, such as weeks of ECMO, in deciding priority. What does this criterion address?','Resource intensity and duration',['Perceived social worth','Type of insurance coverage','Order of arrival at hospital'],'B','Treating several patients briefly may save more lives than treating one for a long time.',EMAN),
  q(CRIT,'U.S. kidney allocation gives priority to which candidates for kidneys from younger, higher-quality donors?','Pediatric candidates',['Candidates over age 70','Candidates with private insurance','Candidates living near the hospital'],'C','The policy recognizes that children suffer more from long periods on dialysis.',OPTN),
  q(CRIT,'The UK’s liver allocation system compares a patient’s expected survival with and without a transplant. What does this approach measure?','Transplant benefit',['Waiting time','Social value','Ability to pay'],'D','Benefit-based scoring tries to balance urgency and expected outcome.',OPTN),
  q(CRIT,'Why do U.S. kidney candidates with very high cPRA scores receive extra priority?','Compatible donor kidneys are rare for them',['They have been on the waiting list for the shortest time','They are always the youngest candidates on the list','They live closest to the busiest transplant centers'],'A','Priority helps highly sensitized patients get a fair chance at the few compatible kidneys.',OPTN),
  q(CRIT,'What is the main ethical criticism of allocating scarce care purely by ability to pay?','It ignores medical need and benefit',['It always wastes resources','It requires a lottery','It favors the youngest patients'],'B','Market allocation can be efficient but lets wealth decide who lives.',BH),
  q(CRIT,'A 2014 WHO report on fair choices toward universal health coverage named three key criteria: cost-effectiveness, priority to the worse off, and what else?','Financial risk protection',['Highest survival rate','Lowest patient age','Order of arrival'],'C','Financial protection keeps families from being impoverished by health costs.',BH),
  q(CRIT,'Why do many experts recommend an appeals process in crisis triage plans?','To review possible errors and keep decisions accountable',['To let wealthy patients buy a higher priority score','To replace the triage officer with family members','To delay every decision by at least a week'],'D','Appeals must be quick so that patients are not harmed by long delays.',EMAN),
  q(CASE,'In 2003, a teenager at Duke University died after receiving a heart and lungs of the wrong blood type. Who was she?','Jesica Santillán',['Sarah Murnaghan','Charlie Gard','Jahi McMath'],'A','The case led to new safeguards to verify blood type before transplants.',OPTN),
  q(CASE,'The cystic fibrosis drug Trikafta has a U.S. list price of about how much per patient per year?','About $300,000',['About $300','About $3,000','About $30 million'],'B','High prices for breakthrough drugs force insurers and governments to make coverage decisions.',BH),
  q(CASE,'Alec Smith’s 2017 death after he rationed his insulin became a symbol of which problem?','High insulin costs for uninsured people',['A national insulin factory fire','Insulin being banned for adults','A shortage of syringes in hospitals'],'C','He could not afford insulin after aging off his parent’s insurance; his story helped drive insulin cost caps.',BH),
  q(CASE,'In 2023 and 2024, millions of people lost Medicaid coverage after pandemic protections ended. What was this process called?','Medicaid unwinding',['Medicaid expansion','Medicaid block granting','Medicaid buy-in'],'D','Many lost coverage for paperwork reasons even though they were still eligible.',BH),
  q(CASE,'In 2021, California set aside 40% of COVID-19 vaccine doses for which communities?','The most disadvantaged areas by a health index',['The wealthiest zip codes in each county of the state','Communities served by the oldest hospital buildings','Only rural counties that had no hospital at all'],'A','The policy aimed to reach the communities hit hardest by the pandemic.',EMAN),
  q(CASE,'England’s NHS sets a target that most patients should start planned hospital treatment within how many weeks of referral?','18 weeks',['2 weeks','52 weeks','104 weeks'],'B','Waiting lists are a form of rationing by delay in tax-funded health systems.',BH),
  q(CASE,'In April 2020, which state revised its crisis standards to remove points for long-term life expectancy after disability advocates objected?','Massachusetts',['South Carolina','New Hampshire','Mississippi'],'C','The change shifted focus to short-term survival during the current illness.',EMAN),
  q(CASE,'In 2022, a COVID-19 lockdown in Shanghai caused a U.S. shortage of which product used in CT scans?','Iodinated contrast dye',['Lead radiation aprons','MRI scanner magnets','Sterile ultrasound gel'],'D','Hospitals postponed some scans and saved contrast for the most urgent cases.',BH),
  q(CASE,'From 2022 to 2024, many U.S. patients struggled to fill prescriptions for which medicines because of production limits and rising demand?','ADHD stimulant medicines',['Antacid tablets','Allergy eye drops','Vitamin D pills'],'A','The shortage forced pharmacies and patients to search widely or switch drugs.',BH),
  q(CASE,'A 2023 shortage of benzathine penicillin G (Bicillin L-A) mainly threatened the treatment of which disease?','Syphilis',['Malaria','Influenza','Tuberculosis'],'B','Health officials prioritized remaining supply for pregnant patients to prevent congenital syphilis.',BH),
  q(AGE,'The WHO’s 2021 Global Report on Ageism describes which three forms of ageism?','Institutional, interpersonal and self-directed',['Federal, state, county and local government ageism','Genetic, hormonal, dietary and environmental ageism','Mild, moderate, severe and extreme forms of ageism'],'C','Self-directed ageism is when people apply age stereotypes to themselves.',LEVY),
  q(AGE,'Regions such as Okinawa and Sardinia, where unusually many people live to very old age, are often called:','Blue Zones',['Green Zones','Red Zones','Safe Zones'],'D','Researchers point to diet, activity, purpose and social ties in these areas.',LEVY),
  q(AGE,'Which theory proposes that older adults who stay socially and physically active age more successfully?','Activity theory',['Disengagement theory','Continuity theory','Exchange theory'],'A','Disengagement theory, by contrast, held that withdrawing from society is natural in old age.',LEVY),
  q(AGE,'Laura Carstensen’s theory that people focus more on emotionally meaningful goals as they sense time is limited is called:','Socioemotional selectivity theory',['Social learning theory','Cognitive dissonance theory','Self-determination theory'],'B','The theory helps explain why many older adults report greater emotional well-being.',LEVY),
  q(AGE,'Why do critics say QALY-based allocation can disadvantage older patients?','Fewer remaining years lowers their scores',['QALYs count only the years a person lives before age 18','QALYs give extra weight to patients over age 65','QALYs ignore length of life and measure only quality'],'C','Supporters respond that QALYs measure benefit, not personal worth.',LEVY),
  q(AGE,'The United Nations declared 2021 to 2030 the Decade of what?','Healthy Ageing',['Clean Oceans','Digital Health','Global Literacy'],'D','The initiative works to combat ageism and improve care for older people.',LEVY),
  q(AGE,'Discussing and recording one’s goals and preferences for future care, before a crisis occurs, is called:','Advance care planning',['Crisis triage','Discharge planning','Utilization review'],'A','Planning ahead helps make sure care at the end of life matches each person’s values.',LEVY),
  q(AGE,'About what is the median age of the U.S. population today?','About 39',['About 25','About 52','About 65'],'B','A rising median age increases demand for health services and long-term care.',LEVY)
 ],9644)
};
